Une pile est une structure de données LIFO (dernier entré, premier sorti), tandis qu'une file est une structure FIFO (premier entré, premier sorti). Voici un exemple simple en C pour illustrer ces concepts.

```c
#include <stdio.h>
#include <stdlib.h>

// Structure pour une pile
typedef struct Node {
    int data;
    struct Node* next;
} Node;

Node* top = NULL;

void push(int data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = data;
    newNode->next = top;
    top = newNode;
}

int pop() {
    if (top == NULL) {
        printf("Pile vide\n");
        return -1; // Ou gérer l'erreur autrement
    }
    int data = top->data;
    Node* temp = top;
    top = top->next;
    free(temp);
    return data;
}

// Structure pour une file
typedef struct QueueNode {
    int data;
    struct QueueNode* next;
} QueueNode;

QueueNode* front = NULL;
QueueNode* rear = NULL;

void enqueue(int data) {
    QueueNode* newNode = (QueueNode*)malloc(sizeof(QueueNode));
    newNode->data = data;
    newNode->next = NULL;
    if (rear == NULL) {
        front = rear = newNode;
        return;
    }
    rear->next = newNode;
    rear = newNode;
}

int dequeue() {
    if (front == NULL) {
        printf("File vide\n");
        return -1; // Ou gérer l'erreur autrement
    }
    int data = front->data;
    QueueNode* temp = front;
    front = front->next;
    if (front == NULL) {
        rear = NULL;
    }
    free(temp);
    return data;
}

int main() {
    printf("--- Pile ---\n");
    push(10);
    push(20);
    printf("Pop: %d\n", pop()); // Affiche 20
    printf("Pop: %d\n", pop()); // Affiche 10

    printf("\n--- File ---\n");
    enqueue(100);
    enqueue(200);
    printf("Dequeue: %d\n", dequeue()); // Affiche 100
    printf("Dequeue: %d\n", dequeue()); // Affiche 200

    return 0;
}
```

Une pile est une structure de données LIFO (dernier entré, premier sorti), tandis qu'une file est une structure FIFO (premier entré, premier sorti). Voici un exemple simple en C pour illustrer ces concepts.

Pour une pile, on peut utiliser un tableau et un pointeur pour gérer l'ajout (push) et le retrait (pop) d'éléments.

```c
#include <stdio.h>
#define MAX_SIZE 100

int stack[MAX_SIZE];
int top = -1;

void push(int value) {
    if (top >= MAX_SIZE - 1) {
        printf("Stack Overflow\n");
    } else {
        stack[++top] = value;
        printf("%d pushed to stack\n", value);
    }
}

int pop() {
    if (top < 0) {
        printf("Stack Underflow\n");
        return -1; // Indicate error
    } else {
        return stack[top--];
    }
}
```

Pour une file, on utilise généralement un tableau circulaire ou une liste chaînée pour gérer l'ajout (enqueue) à la fin et le retrait (dequeue) au début.

```c
#include <stdio.h>
#define MAX_SIZE 100

int queue[MAX_SIZE];
int front = 0;
int rear = -1;
int itemCount = 0;

void enqueue(int value) {
    if (itemCount >= MAX_SIZE) {
        printf("Queue Overflow\n");
    } else {
        queue[++rear] = value;
        itemCount++;
        printf("%d enqueued to queue\n", value);
    }
}

int dequeue() {
    if (itemCount <= 0) {
        printf("Queue Underflow\n");
        return -1; // Indicate error
    } else {
        itemCount--;
        return queue[front++];
    }
}
```

