Une file d'attente est une structure de données "premier entré, premier sorti" (FIFO), tandis qu'une pile est une structure "dernier entré, premier sorti" (LIFO). Pour une file, on ajoute des éléments à la fin et on retire du début. Pour une pile, on ajoute et retire du sommet.

Voici un exemple simple en C pour illustrer le concept d'une pile :

```c
#include <stdio.h>
#include <stdlib.h>

#define MAX_SIZE 100

int stack[MAX_SIZE];
int top = -1;

void push(int item) {
    if (top >= MAX_SIZE - 1) {
        printf("Stack Overflow\n");
        return;
    }
    stack[++top] = item;
}

int pop() {
    if (top < 0) {
        printf("Stack Underflow\n");
        return -1; // Or handle error appropriately
    }
    return stack[top--];
}

int main() {
    push(10);
    push(20);
    printf("Popped: %d\n", pop()); // Outputs: Popped: 20
    return 0;
}
```

Une file est une structure de données qui suit le principe du premier entré, premier sorti (FIFO), comme une file d'attente. Une pile suit le principe du dernier entré, premier sorti (LIFO), comme une pile d'assiettes. Voici un exemple simple en C pour illustrer ces concepts.

```c
#include <stdio.h>
#include <stdlib.h>

// Pile
#define MAX_SIZE 100
int stack[MAX_SIZE];
int top = -1;

void push(int x) {
    if (top >= MAX_SIZE - 1) {
        printf("Stack Overflow\n");
        return;
    }
    stack[++top] = x;
}

int pop() {
    if (top < 0) {
        printf("Stack Underflow\n");
        return -1;
    }
    return stack[top--];
}

// File
typedef struct Node {
    int data;
    struct Node* next;
} Node;

Node* front = NULL;
Node* rear = NULL;

void enqueue(int x) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = x;
    newNode->next = NULL;
    if (rear == NULL) {
        front = rear = newNode;
        return;
    }
    rear->next = newNode;
    rear = newNode;
}

int dequeue() {
    if (front == NULL) {
        printf("Queue Underflow\n");
        return -1;
    }
    Node* temp = front;
    int data = temp->data;
    front = front->next;
    if (front == NULL) {
        rear = NULL;
    }
    free(temp);
    return data;
}

int main() {
    // Pile example
    push(10);
    push(20);
    printf("Popped from stack: %d\n", pop()); // 20

    // File example
    enqueue(10);
    enqueue(20);
    printf("Dequeued from queue: %d\n", dequeue()); // 10

    return 0;
}
```
